public void activateNukeVirus(int pos) {
        int neighbour = getHackedNeighbour(pendingNukePos);
        if (neighbour >= 0) {
            boolean found = false;
            Node neighbourNode = getNodeAt(neighbour);
            if (neighbourNode != null) {
                for (Pair<Integer, Float> conn : neighbourNode.outGoingHacks) {
                    if (conn.getLeft() == pendingNukePos) {
                        conn.setValue(1f);
                        found = true;
                    }
                }
                if (!found) {
                    neighbourNode.outGoingHacks.add(Pair.of(pendingNukePos, 1f));
                }
                Node node = getNodeAt(pos);
                if (node != null) {
                    node.setHackProgress(pos, 1f, false);
                }
                if (controller != null) controller.getHacker().playSound(SoundEvents.GENERIC_EXPLODE.value(), 1f, 1f);
                nukeVirusCooldown = 60;
            }
        }
        pendingNukePos = -1;
    }

public void tick() {
        if (hackComplete) return;

        isStarted = true;

        if (stopWormTimer > 0) {
            stopWormTimer--;
        }
        if (nukeVirusCooldown > 0) {
            nukeVirusCooldown--;
        }

        allConnections.clear();
        int nonNullNodes = 0;
        int completeNodes = 0;
        for (int i = 0; i < nodes.length; i++) {
            Node node = getNodeAt(i);
            if (node == null) continue;
            nonNullNodes++;

            int f = node.fortification;
            node.tick();
            if (controller != null && f < NODE_FORTIFICATION_TIME && node.fortification == NODE_FORTIFICATION_TIME) {
                controller.onNodeFortified(this, i);
            }

            if (side == HackingSide.AI && isAwake() && (isDummy() || node.isHacked()) && node.outGoingHacks.isEmpty()) {
                // start the trace to all neighbouring nodes
                for (int neighbourPos : getNeighbours(i)) {
                    Node neighbourNode = getNodeAt(neighbourPos);
                    if (neighbourNode != null && (isDummy() || !neighbourNode.isHacked())) {
                        // found an unhacked neighbour
                        node.startHacking(i, neighbourPos);
                    }
                }
            }

            if (pendingNukePos == i) {
                activateNukeVirus(i);
            }

            // update all in-progress connections
            int finishedConns = 0;
            for (Pair<Integer, Float> conn : node.outGoingHacks) {
                if (conn.getValue() < 1F) {
                    if (stopWormTimer == 0) {
                        Node targetNode = getNodeAt(conn.getKey());
                        if (targetNode != null) {
                            conn.setValue(Math.min(1F, conn.getValue() + targetNode.getProgressPerTick()));
                            targetNode.setHackProgress(conn.getKey(), conn.getValue(), true);
                        }
                    }
                } else {
                    finishedConns++;
                }
                allConnections.add(new ConnectionEntry(i, conn.getKey(), conn.getValue()));
            }
            if (finishedConns == node.outGoingHacks.size() && !node.outGoingHacks.isEmpty()) completeNodes++;
        }
        if (completeNodes >= nonNullNodes) {
            hackComplete = true;
        }
    }

public boolean initiateNukeVirus(int pos) {
        Validate.isTrue(pos >= 0 && pos < GRID_SIZE, "nuke position " + pos + " out of range!");
        Node node = getNodeAt(pos);
        if (node != null && pendingNukePos < 0 && isNukeVirusReady()
                && node.type != NetworkComponentType.DIAGNOSTIC_SUBROUTINE
                && node.type != NetworkComponentType.NETWORK_REGISTRY)
        {
            pendingNukePos = pos;
            return true;
        } else {
            return false;
        }
    }

public int getHackedNeighbour(int nodePos) {
        for (int n2 : getNeighbours(nodePos)) {
            Node node2 = getNodeAt(n2);
            if (node2 != null && node2.isHacked()) {
                return n2;
            }
        }
        return -1;
    }

@Override
    public void handleGUIButtonPress(String tag, boolean shiftHeld, ServerPlayer player) {
        if (rsController.parseRedstoneMode(tag)) return;

        if (player.containerMenu instanceof SecurityStationMainMenu && isPlayerOnWhiteList(player)) {
            if (tag.equals("reboot")) {
                rebootStation();
            } else if (tag.equals("test") && ConfigHelper.common().machines.securityStationAllowHacking.get()) {
                if (hasValidNetwork()) {
                    initiateHacking(player);
                } else {
                    player.displayClientMessage(Component.translatable("pneumaticcraft.message.securityStation.outOfOrder"), false);
                }
            } else if (tag.startsWith("remove:") && isOwner(player)) {
                String name = tag.split(":", 2)[1];
                removeTrustedUser(name);
            } else if (tag.startsWith("add:") && isOwner(player)) {
                String name = tag.split(":", 2)[1];
                PneumaticCraftUtils.getProfileForName(player.getServer(), name).ifPresent(this::addTrustedUser);
            }
        } else if (player.containerMenu instanceof SecurityStationHackingMenu && isPlayerHacking(player)) {
            if (tag.equals("end_test") && simulationController.isJustTesting()) {
                player.openMenu(this, getBlockPos());
            } else if (tag.startsWith("nuke:")) {
                tryNukeVirus(tag, player);
            } else if (tag.equals("stop_worm")) {
                tryStopWorm(player);
            } else if (tag.startsWith("fortify:")) {
                tryFortify(tag, player);
            } else if (tag.startsWith("hack:")) {
                tryHack(tag, player);
            }
        }
        sendDescriptionPacket();
    }

private boolean isPlayerHacking(Player player) {
        return simulationController != null
                && simulationController.getHacker().isAlive()
                && simulationController.getHacker().equals(player);
    }

private void tryNukeVirus(String tag, Player player) {
        try {
            if (PneumaticCraftUtils.consumeInventoryItem(player.getInventory(), ModItems.NUKE_VIRUS.get())) {
                int nodePos = Integer.parseInt(tag.split(":", 2)[1]);
                simulationController.getSimulation(HackingSide.PLAYER).initiateNukeVirus(nodePos);
            } else {
                // client is lying about how many nuke viruses they have!
                player.kill();
            }
        } catch (IllegalArgumentException | IndexOutOfBoundsException e) {
            Log.warning("security station @ {}: ignoring bad message {}} from {}}",
                    PneumaticCraftUtils.posToString(worldPosition), tag, player.getGameProfile().getName());
        }
    }

@Override
    public void entityInside(@NotNull BlockState state, @NotNull Level worldIn, @NotNull BlockPos pos, @NotNull Entity entityIn) {
        super.entityInside(state, worldIn, pos, entityIn);
        List<Entity> entities = worldIn.getEntitiesOfClass(Entity.class, getShape(state, worldIn, pos, CollisionContext.empty()).bounds().move(pos), EntitySelector.NO_SPECTATORS.and((p_289691_) -> {
            return !p_289691_.isIgnoringBlockTriggers();
        }));
        if (!entities.isEmpty() && worldIn.getBlockEntity(pos) instanceof RuneTile rune) {
            if (rune.spell != null) {
                // Ignore form and its augment, only check effects
                for (AbstractSpellPart part : rune.spell.recipe()) {
                    if (part instanceof AbstractEffect) {
                        // If the effect is not a filter, proceed with rune activation
                        if (part instanceof IFilter filter) {
                            // If one or more filters are detected, all must match to let the rune activate
                            if (!filter.shouldResolveOnEntity(new EntityHitResult(entityIn), worldIn)) {
                                return;
                            }
                        } else break;
                    }
                }
            }
            rune.touchedEntity = entities.getFirst();
            worldIn.scheduleTick(pos, this, 1);
        }
    }

@Override
    public void tick(@NotNull BlockState state, @NotNull ServerLevel worldIn, @NotNull BlockPos pos, @NotNull RandomSource rand) {
        super.tick(state, worldIn, pos, rand);

        if (worldIn.getBlockEntity(pos) instanceof RuneTile rune && rune.touchedEntity != null) {
            rune.castSpell(rune.touchedEntity);
            rune.touchedEntity = null;
