        tag.putString("pattern", pattern);
    }

@Override
    protected void loadAdditional(@NotNull CompoundTag tag, HolderLookup.@NotNull Provider pRegistries) {
        super.loadAdditional(tag, pRegistries);
        this.spell = ANCodecs.decode(Spell.CODEC.codec(), tag.getCompound("spell"));
        this.isCharged = tag.getBoolean("charged");
        this.disabled = tag.getBoolean("redstone");
        this.isTemporary = tag.getBoolean("temp");
        this.ticksUntilCharge = tag.getInt("cooldown");
        if (tag.contains("uuid"))
            this.uuid = tag.getUUID("uuid");
        this.isSensitive = tag.getBoolean("sensitive");
        this.pattern = tag.getString("pattern");
    }

private void processApplicableRecipes() {
        for (ApplicableRecipe applicableRecipe : applicableRecipes) {
            PressureChamberRecipe recipe = applicableRecipe.recipe;
            float requiredPressure = recipe.getCraftingPressure(itemsInChamber, applicableRecipe.slots);
            boolean pressureOK = requiredPressure <= getPressure() && requiredPressure > 0F
                    || requiredPressure >= getPressure() && requiredPressure < 0F;
            if (Math.abs(requiredPressure) < Math.abs(recipePressure)) {
                recipePressure = requiredPressure;
            }
            if (pressureOK) {
                // let's craft! (although if the output handler is full, we won't...)
                isSufficientPressureInChamber = true;
                if (giveOutput(recipe.craftRecipe(itemsInChamber, applicableRecipe.slots, true), true)
                        && giveOutput(recipe.craftRecipe(itemsInChamber, applicableRecipe.slots, false), false)) {
                    if (nonNullLevel().getGameTime() - lastSoundTick > 5) {
                        nonNullLevel().playSound(null, getBlockPos(), SoundEvents.CHICKEN_EGG, SoundSource.BLOCKS, 0.7f, 0.8f);
                        lastSoundTick = nonNullLevel().getGameTime();
                    }
                }
                // Craft at most one recipe each tick; this is because crafting changes the contents of the
                // chamber, possibly invalidating other applicable recipes.  Modifying the chamber's contents
                // automatically triggers a rescan for applicable recipes on the next tick.
                break;
            }
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        checkForAirLeak();

        if (multiBlockSize != 0) {
            roundedPressure = ((int) (getPressure() * 4.0f)) / 4.0f;
            checkForRecipeRecalc();
            processApplicableRecipes();
            if (getPressure() > PneumaticValues.MAX_PRESSURE_LIVING_ENTITY) {
                handleEntitiesInChamber();
            }
        }
    }

private void checkForRecipeRecalc() {
        if (recipeRecalcNeeded) {
            isValidRecipeInChamber = false;
            isSufficientPressureInChamber = false;
            recipePressure = Float.MAX_VALUE;
            applicableRecipes.clear();
            final SizeLimitedItemHandlerWrapper h = new SizeLimitedItemHandlerWrapper(itemsInChamber);
            if (h.getSlots() > 0) {
                ModRecipeTypes.PRESSURE_CHAMBER.get().stream(level).map(RecipeHolder::value).forEach(recipe -> {
                    IntCollection slots = recipe.findIngredients(h);
                    if (!slots.isEmpty()) {
                        applicableRecipes.add(new ApplicableRecipe(recipe, slots));
                    }
                });
            }
            isValidRecipeInChamber = !applicableRecipes.isEmpty();
            // if we can't find a valid recipe, try coalescing itemstack in the chamber
            // it's possible we have the right ingredients, but split across stacks
            recipeRecalcNeeded = !isValidRecipeInChamber && coalesceItems();
        }
    }

private boolean giveOutput(List<ItemStack> stacks, boolean simulate) {
        if (stacks.isEmpty()) return false;
        for (ItemStack stack : stacks) {
            stack = stack.copy();
            ItemStack result = ItemHandlerHelper.insertItem(craftedItems, stack, simulate);
            if (!result.isEmpty()) return false;
        }
        return true;
    }

@Override
    protected void tick() {

        ParticleUtil.spawnFallingSkyEffect(this, tile, rand, getCenterColor().toWrapper());
        if (getWorld().getGameTime() % 20 == 0 && !getWorld().isClientSide)
            incrementProgress();

        if (!getWorld().isClientSide && getProgress() >= 15) {
            List<ServerPlayer> players = getWorld().getEntitiesOfClass(ServerPlayer.class, new AABB(getPos()).inflate(5.0));
            if (!players.isEmpty()) {
                ItemStack item = getConsumedItems().stream().filter(i -> i.getItem() != ItemsRegistry.MANIPULATION_ESSENCE.get()).findFirst().orElse(ItemStack.EMPTY);
                int modifier = didConsumeItem(ItemsRegistry.MANIPULATION_ESSENCE.get()) ? 3 : 1;
                for (ServerPlayer playerEntity : players) {
                    Optional<ScryRitualRecipe> hasRecipe = ScryRitualRegistry.getRecipes().stream().filter(recipe -> recipe.matches(new SingleRecipeInput(item), getWorld())).findFirst();
                    IScryer scryer = null;
                    if (hasRecipe.isPresent()) scryer = new TagScryer(hasRecipe.get().highlight());
                    else if (item.getItem() instanceof BlockItem blockItem)
                        scryer = new SingleBlockScryer(blockItem.getBlock());
                    if (scryer != null) {
                        RitualScrying.grantScrying(playerEntity, 60 * 20 * 5 * modifier, scryer);
                    }
                }
            }
            setFinished();
        }
    }

public static void grantScrying(ServerPlayer playerEntity, int ticks, IScryer scryer) {
        playerEntity.addEffect(new MobEffectInstance(ModPotions.SCRYING_EFFECT, ticks));
        CompoundTag tag = playerEntity.getPersistentData().getCompound(Player.PERSISTED_NBT_TAG);
        tag.put("an_scryer", scryer.toTag(new CompoundTag()));
        playerEntity.getPersistentData().put(Player.PERSISTED_NBT_TAG, tag);
        Networking.sendToPlayerClient(new PacketGetPersistentData(tag), playerEntity);
    }

@SubscribeEvent
